-- Canada: international admission info, English/SAT/WASSCE minimums (undergraduate programs), and school scholarships.

-- From each university's official website, Nov 2026. Safe to re-run.

begin;

update schools s set admission_info=v.j, admission_link=coalesce(v.link,s.admission_link), admission_checked=current_date
from (values
('1263a1a6-98e8-42a9-8acd-2fd9acd61976','{"ug": "Carleton''s admission requirements tool lists ''West Africa - WAEC'' as an accepted curriculum, but the minimum grades and subjects for WAEC applicants are not stated on the pages reviewed. For English, undergraduates need IELTS Academic 6.5 (6.0 in each band), TOEFL iBT 86 (tests before Jan 21, 2026) or 4.5 on the new scale, or Duolingo 120; Ghana is on the list of English-speaking countries, so three years of full-time study in English there can waive the test. SAT: Not stated on the official site. The main deadline for international applicants is April 1, 2027 for September 2027 entry, and some programs have earlier deadlines.", "sources": ["https://admissions.carleton.ca/esl"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "April 1, 2027: main deadline for international applicants (transcripts from outside Canada/US) for Fall 2027; some programs have earlier deadlines."}'::jsonb,'https://admissions.carleton.ca/esl'),
('e6e07660-48f0-420f-97ec-4dd4c8264457','{"ug": "Université Laval teaches in French. For undergraduate entry from Ghana it asks for a pre-university diploma covering 12 years of education plus one year of post-secondary study; it lists the GCE A Level (3 A levels) and the Senior Secondary School Certificate (SSCE) as Ghanaian credentials. Applicants who fall short may first need a qualifying year at Laval, offered only for programs without limited enrolment. Non-francophone applicants must take the TCF tout public French test, and no English test (IELTS, TOEFL, Duolingo) is required. SAT: Not stated on the official site. International applicants must apply by February 1 for fall entry, or November 1 of the year before for medicine, pharmacy, occupational therapy, physiotherapy, sexology and biomedical sciences.", "sources": ["https://www.ulaval.ca/en/ulaval-experience/international-applicants/academic-equivalence"], "deadlines": "February 1 for fall (undergraduate, international applicants); November 1 of the previous year for medicine, pharmacy, occupational therapy, physiotherapy, sexology and biomedical sciences."}'::jsonb,'https://www.ulaval.ca/en/ulaval-experience/international-applicants/academic-equivalence'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','{"ug": "Acadia accepts Ghanaian WAEC results and asks for five grades of C or better, including English Language. Undergraduates need IELTS 6.5 (no band below 6.0), TOEFL iBT 90 (no section below 20) or Duolingo 115 (no subscore below 90); three years of English-medium study may waive this, and an English for Academic Purposes route is available. SAT: Not stated on the official site. Applications open after October 1; to be considered for entrance scholarships, apply by March 1. A general fall application deadline is not stated on the official site.", "sources": ["https://acadiau.ca/admissions/application-process/international-students.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 115.", "deadlines": "Applications open after October 1; apply by March 1 for entrance scholarship consideration (no general fall deadline stated)."}'::jsonb,'https://acadiau.ca/admissions/application-process/international-students.html'),
('890bc234-8faf-4dcf-b8c5-da0dc787961a','{"ug": "Emily Carr does not mention WAEC or WASSCE. For other international schools, it asks for the highest secondary qualification that leads to university, with at least 67% (C+) across five courses that match BC requirements, plus a portfolio, which counts for most of the admission score. Undergraduates need IELTS Academic 6.5 (6.0 in each part), TOEFL iBT 84 or Duolingo 110; four years of English-medium secondary school in Ghana counts as an exemption. The SAT and ACT are not required. For Fall 2027, apply through EducationPlannerBC and send transcripts by January 15, 2027, then submit the portfolio by January 31, 2027.", "sources": ["https://ecuad.ca/?p=3081"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 84, Duolingo 110.", "deadlines": "Fall 2027: apply and submit transcripts by January 15, 2027; portfolio by January 31, 2027 (applications open October 1, 2026)."}'::jsonb,'https://ecuad.ca/?p=3081'),
('94f34f2e-2f9d-4140-bf3e-f723ea13a7b0','{"ug": "Mount Royal lists the WAEC Senior School Certificate Examination as the accepted Ghanaian credential, but it does not state minimum grades; admission is competitive and grades vary by program. Undergraduates need IELTS Academic 6.5 (5.5 in each band), TOEFL iBT 86 (20 in each section, tests before Jan 21, 2026) or 4.5 on the new scale, or Duolingo 120. Ghana is on its list of English-speaking countries for a study-based exemption, which also needs English 30-1/30-2 or an equivalent. SAT: Not stated on the official site. For fall, international applicants must apply by April 1 and send documents by May 1, although some programs close February 1.", "sources": ["https://www.mtroyal.ca/InternationalStudents/Admissionrequirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Fall: apply by April 1 and send documents by May 1 (international); some programs close February 1. Apply by February 1 to be eligible for entrance awards."}'::jsonb,'https://www.mtroyal.ca/InternationalStudents/Admissionrequirements'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','{"ug": "StFX accepts WASSCE results from Ghana; send them with the details needed to verify them online. No minimum WASSCE grades are stated, and the general high school minimum is a 70% average with no required subject below 65%. Undergraduates need IELTS 6.5 (no band below 6.0), TOEFL iBT 90 (no band below 20) or Duolingo 115 (no subscore below 100); two years of English-medium study can waive this. SAT and ACT are said to be not required in the US section, and the site says nothing for other international applicants. The international application deadline for Fall 2027 is May 30, 2027, and March 1, 2027 is the deadline for applying with major scholarship consideration.", "sources": ["https://www.stfx.ca/applications-admissions/admissions-information/admission-requirements/high-school"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 115.", "deadlines": "Fall 2027: international applications by May 30, 2027 (later ones handled case by case); admission plus scholarship application by March 1, 2027."}'::jsonb,'https://www.stfx.ca/applications-admissions/admissions-information/admission-requirements/high-school'),
('4c3f0735-e2c3-4792-8c4f-042e744ce793','{"ug": "UQAR teaches in French. For a bachelor''s degree it asks for a diploma representing at least 13 years of schooling, equivalent to a Quebec DEC, and points applicants to its Guide des niveaux de formation by country; Ghana and WAEC are not mentioned on the pages reviewed. Most applicants with a foreign diploma must send an international French test result with the application (TEF or TCF 460, or Bright Language 3.5), and no English test (IELTS, TOEFL, Duolingo) is required for undergraduate study. SAT: Not stated on the official site. For Fall 2027, applications open September 1, 2026 and close March 1, 2027.", "sources": ["https://www.uqar.ca/programmes-formations-et-admission/admission/etudiant-es-etrangers/admission-pour-etudiants-internationaux/"], "deadlines": "Fall 2027: applications open September 1, 2026 and close March 1, 2027."}'::jsonb,'https://www.uqar.ca/programmes-formations-et-admission/admission/etudiant-es-etrangers/admission-pour-etudiants-internationaux/'),
('03b25832-0531-4f09-ab3a-c82deba3bbde','{"ug": "UPEI accepts Ghanaian applicants with transcripts for grades 10 to 12 plus the WAEC senior secondary certificate, and asks for at least a 3 in the subjects their program requires (and at least a 3 in Math for some science programs). Undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 80 (20 in each section) or Duolingo 120; nursing, radiography, education and veterinary medicine need higher scores, and three years of full-time study in an English-speaking country can count instead. The SAT is not required for US applicants and can be used for scholarships, but nothing is said for other international applicants. Fall application deadline: Not stated on the official site, and early applications are encouraged.", "sources": ["https://d9.upei.ca/node/20491"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 80, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://d9.upei.ca/node/20491'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','{"ug": "Concordia accepts the WASSCE from Ghana and says that applicants who have finished the schooling needed to enter university in their home country, with good grades, should generally be eligible; minimum WASSCE grades are not stated, and averages vary by program. Undergraduates need IELTS Academic 6.0 (no part below 5.5), TOEFL iBT 70 (tests before January 2026) or 4.0 on the new scale, or Duolingo 105 (no subscore below 90); Ghana is on the list of countries where three years of study in English can exempt you from a test. The SAT and ACT are said to be not required for American and Canadian applicants, with nothing said for Ghana. For September entry, international applicants should apply by February 1 (March 1 is the general deadline).", "sources": ["https://www.concordia.ca/admissions/undergraduate/international/africa.html"], "english": "Undergraduate minimums: IELTS 6.0, TOEFL iBT 70, Duolingo 105.", "deadlines": "Fall (September): February 1 for U.S. and international applicants (to allow time for immigration documents); March 1 general deadline."}'::jsonb,'https://www.concordia.ca/admissions/undergraduate/international/africa.html'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','{"ug": "The University of Alberta accepts WASSCE results from Ghana and asks for five subjects, which depend on the program; minimum grades are not stated. It must check the results itself, so you send official WAEC results or scratch-card details, not copies. Undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 90 (no section below 21, tests before Jan 21, 2026) or 4.5 on the new scale, or Duolingo 120 (no subscore below 100). SAT: Not stated on the official site. For Fall 2027 most programs close on March 1, 2027, and final documents are due June 15, 2027.", "sources": ["https://www.ualberta.ca/en/admissions/how-to-apply/international-admission-requirements/international-curricula/west-africa.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 120.", "deadlines": "Fall 2027: apply by March 1, 2027 for most programs (some have other dates); documents due June 15, 2027. Apply for scholarships by January 10."}'::jsonb,'https://www.ualberta.ca/en/admissions/how-to-apply/international-admission-requirements/international-curricula/west-africa.html'),
('25decb60-25d8-47e8-8835-9c35ed464d65','{"ug": "Algoma accepts the WAEC West African Senior School Certificate from Ghana and asks for at least five subjects, including the required courses, all at C5 or better; one C6 is allowed if it is not in a required course. Most undergraduate programs need IELTS Academic 6.0 (no band below 6.0) or Duolingo 110 (no band below 90); Biology and Psychology need IELTS 6.5 or Duolingo 110 with no band below 95. TOEFL is listed on the new scale: 4.0, or 4.5 for Biology and Psychology. Ghana is on the exemption list, but exemption is not automatic. SAT and the fall application deadline: Not stated on the official site.", "sources": ["https://algomau.ca/students/international-students/admissions-requirements/"], "english": "Undergraduate minimums: IELTS 6.0, Duolingo 110.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://algomau.ca/students/international-students/admissions-requirements/'),
('66916c52-54ff-4d03-b765-f1289349f38a','{"ug": "MSVU accepts the WASSCE from Ghana with grades of C5 or better (or the older SSSCE with grades A, B and C), and secondary applicants generally need a 70% average in their five best academic subjects. Undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 86-92 (no section below 21) or Duolingo 115 (no subscore below 95). The SAT is not required but may be submitted as extra evidence; this wording appears in the US section. The international undergraduate deadline for September 2027 is May 3, 2027.", "sources": ["https://msvu.ca/future-students/admission-requirements/international-students"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 115.", "deadlines": "September 2027: international undergraduate applicants by May 3, 2027."}'::jsonb,'https://msvu.ca/future-students/admission-requirements/international-students'),
('c50b6fa3-e068-4a5c-9a56-4ac3226e73e4','{"ug": "St. Thomas accepts WASSCE results from Ghana and asks for an average of C4 across five academic subjects, including English. Results must come directly from WAEC or be verified with a scratch card, and your school must also send a transcript. To take a full course load, you need IELTS 6.5, TOEFL iBT 89 or Duolingo 115; lower scores (IELTS 5.0, TOEFL 61, Duolingo 90) can lead to admission into the ESL program. SAT: Not stated on the official site. Apply by June 1 for September entry; later applications are accepted, but visas may be delayed.", "sources": ["https://communications.stu.ca/international-admissions"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 89, Duolingo 115.", "deadlines": "June 1 for September admission (recommended date; later applications accepted)."}'::jsonb,'https://communications.stu.ca/international-admissions'),
('43f9c4b4-d402-4679-9eaf-a8c36e64fc21','{"ug": "Regina lists Ghana as a country with its own admission requirements, but the WASSCE/WAEC minimum grades are not stated in the page text that could be read; the calendar says non-Canadian applicants need secondary-level standing and faculty minimum averages (for example 70% for Arts, Business and Science). Most undergraduate programs (not Education or Nursing) need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 83 (20 per section, tests before Jan 21, 2026) or 4.5 on the new scale, or Duolingo 120 with set subscores; schooling in Ghana is on the list that may meet the English requirement, decided case by case. SAT: Not stated on the official site. The 2026-27 calendar gives August 15 as the final fall deadline for international applicants, but you must apply by April 30 to be considered for the International Student of Distinction Scholarship.", "sources": ["https://www.uregina.ca/admissions/undergraduate/elp.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 120.", "deadlines": "Fall: final deadline August 15 for international applicants (2026-27 calendar; no early deadline for international applicants); apply by April 30 for fall to be considered for the International Student of Distinction Scholarship."}'::jsonb,'https://www.uregina.ca/admissions/undergraduate/elp.html'),
('3195b66c-ab3e-48c2-b583-c5a589b150a2','{"ug": "UQTR teaches in French. Its international student guide does not state general diploma requirements, WASSCE/WAEC rules or minimum grades; check each program''s admission conditions. Some international applicants must take UQTR''s institutional French test (TIFEI), as stated in the admission letter, and English tests (IELTS, TOEFL, Duolingo) are not mentioned. SAT: Not stated on the official site. The autumn application deadline for programs without enrolment limits is April 1, and dates can change.", "sources": ["https://oraprdnt.uqtr.uquebec.ca/portail/docs/GSC932/O0006041022_REP_international_VF_web_20240719_JB.pdf"], "deadlines": "April 1 for autumn (programs without enrolment limits); dates may change, see uqtr.ca/calendrier."}'::jsonb,'https://oraprdnt.uqtr.uquebec.ca/portail/docs/GSC932/O0006041022_REP_international_VF_web_20240719_JB.pdf'),
('3a2455d2-432a-44d5-a011-522c43a4c630','{"ug": "First Nations University says international students are admitted through the University of Regina''s International Office, and asks applicants to contact International Admissions about requirements. WASSCE/WAEC acceptance and grades: Not stated on the official site. English test minimums: Not stated on the official site. SAT and the fall application deadline: Not stated on the official site.", "sources": ["https://www.fnuniv.ca/admissions/international-students/"], "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.fnuniv.ca/admissions/international-students/'),
('94adc91b-a5f8-4c63-b909-a4a918a7517d','{"ug": "Dalhousie accepts WASSCE results from Ghana; applicants must submit the details needed to verify results on WAEC Direct, and admission is based on subjects studied and grades achieved (minimum grades not stated on the official site). English minimums for undergraduate: IELTS 6.5 (no band below 6.0), TOEFL 90 (min 20 per band), Duolingo 120; students with 3 years at an English-based secondary school are generally considered to meet the requirement. SAT policy: Not stated on the official site. Fall application deadline: Not stated on the official site; the General Entrance Award application deadline is February 15, 2027.", "sources": ["https://www.dal.ca/admissions/how-to-apply/undergraduate-admissions/international-applicants/international-admissions-requirements-by-country.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.dal.ca/admissions/how-to-apply/undergraduate-admissions/international-applicants/international-admissions-requirements-by-country.html'),
('058d3791-8d23-4e86-aeb3-c49071ef58c3','{"ug": "Whether WASSCE results are accepted, and the grades required, is not stated on the official site pages read. Ghana is listed as an English-language-requirement exempt country; otherwise undergraduate minimums are IELTS Academic 6.5, TOEFL iBT 86 (for tests before January 21, 2026) and Duolingo 120, with higher scores for Nursing and Education. SAT policy: Not stated on the official site. International applicants studying outside Canada can apply from August 15 to April 1 (application fee $145).", "sources": ["https://ucalgary.ca/future-students/undergraduate/admissions/how-to-apply"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Applications for international students studying outside Canada open August 15 and close April 1"}'::jsonb,'https://ucalgary.ca/future-students/undergraduate/admissions/how-to-apply'),
('14adea28-4bd9-4410-8bcc-96ebce340d43','{"ug": "Athabasca is mainly an online university; its official page says a Canadian study permit cannot be issued for online programs and no letters of acceptance are given for online programs. Whether WASSCE results are accepted or required: Not stated on the official site. English minimums for undergraduate: IELTS Academic 6.0, TOEFL iBT 80 (essay 20; tests before Jan 21, 2026), Duolingo 105 (75 per band); finishing high school in an English-speaking country is one way to meet the requirement. SAT: Not stated on the official site. No fixed fall deadline; students are advised to register at least a month before a course starts.", "sources": ["https://www.athabascau.ca/admissions/international-students.html"], "english": "Undergraduate minimums: IELTS 6.0, TOEFL iBT 80, Duolingo 105.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.athabascau.ca/admissions/international-students.html'),
('e249725f-8a30-4cea-9579-bc63c9d77418','{"ug": "HEC Montréal''s undergraduate BBA (B.A.A.) is taught in French or in French and English, and non-francophone applicants must prove advanced intermediate French. Applicants educated abroad need a high school diploma (normally 12 years) plus either an HEC preparatory year or one year (30 credits) of university with required maths; WASSCE is not named on the official pages read. No English test minimum is set for BBA admission (admitted students take an English placement test). SAT: Not stated on the official site. Fall application deadline: Not stated on the official site pages read.", "sources": ["https://www.hec.ca/sites/default/files/2025-10/official-description-bba.pdf"], "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.hec.ca/sites/default/files/2025-10/official-description-bba.pdf'),
('977a83eb-de2f-4300-a44e-446400aa121d','{"ug": "Nipissing shows country-specific requirements through an interactive selector, and WASSCE/WAEC rules for Ghana were not readable on the official pages, so minimum grades are Not stated on the official site. English minimums for undergraduate: IELTS Academic 6.5 (no band below 6.0) and TOEFL iBT 83 (Nursing higher); Duolingo is not mentioned; three years of full-time English-medium schooling in an English-dominant country can exempt you. SAT: Not stated on the official site. International applicants can start in Fall (September) or Winter (January); applications received by April 1 are considered for automatic entrance scholarships.", "sources": ["https://nipissingu.ca/applyinternational"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83.", "deadlines": "Apply by April 1 to be considered for entrance scholarships (fall entry); full admission deadline not stated on pages read"}'::jsonb,'https://nipissingu.ca/applyinternational'),
('6f88aa65-32f6-4164-aea2-fa65da5c34a7','{"ug": "UWinnipeg accepts the WASSCE from Ghana: you need 5 academic passes including English, with an average of B (B3), and you must send a copy of the certificate and the WAEC scratch card for online verification. Ghanaian WASSCE applicants are exempt from an English test; otherwise the undergraduate minimums are IELTS Academic 6.5, TOEFL iBT 86 (20 per section) and Duolingo 120. SAT: Not stated on the official site. The international application deadline for Fall (September) entry is June 1, and applying early is recommended.", "sources": ["https://uwinnipeg.ca/future-student/international/countries-a-to-z/-g-.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Fall (September) entry: June 1"}'::jsonb,'https://uwinnipeg.ca/future-student/international/countries-a-to-z/-g-.html'),
('e1cbc7c8-d7ae-4d36-a36a-84bb2163ad9d','{"ug": "UQAT teaches in French. For a bachelor''s degree, international applicants need a suitable diploma earned after at least 13 years of schooling, so a WASSCE alone (12 years) may not be enough; WASSCE is not named on the official site. English and French test minimums: Not stated on the official site pages read. SAT: Not stated on the official site. The application deadline for the fall (autumn) term for international students is February 1.", "sources": ["https://www.uqat.ca/etudes/guide-des-etudes/pdf/etudiantsinternationaux.pdf"], "deadlines": "Fall (autumn) term: February 1"}'::jsonb,'https://www.uqat.ca/etudes/guide-des-etudes/pdf/etudiantsinternationaux.pdf'),
('cc9dd73d-3c07-42ec-a5db-904386ccebb7','{"ug": "UFV requires upper secondary qualifications equivalent to Canadian Grade 12, and each program sets its own entrance requirements; WASSCE/WAEC rules and minimum grades are Not stated on the official site. English minimums for bachelor''s programs: IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (no section below 20), Duolingo 110; no Ghana/WAEC exemption is stated. SAT: Not stated on the official site. Fall (September) applications are accepted from October 1 to June 1, and some programs may close early.", "sources": ["https://international.ufv.ca/future-students/apply-to-ufv/admission-requirements/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 110.", "deadlines": "Fall semester: October 1 to June 1 (some programs may close early)"}'::jsonb,'https://international.ufv.ca/future-students/apply-to-ufv/admission-requirements/'),
('b6fb2eeb-1cca-4d51-83c5-265e609c32f5','{"ug": "McGill lists Ghana''s Senior Secondary School Certificate as an accepted credential, with a minimum of the equivalent of a B+ average, though most programs require more. Admission looks at yearly averages and prerequisite subjects from the last two years of high school (for example, Science needs pre-calculus maths and two of biology, chemistry or physics). English minimums for undergraduate: IELTS Academic 6.5 (6.0 per component), TOEFL iBT 90 for most programs, Duolingo 125; you are exempt if you lived and studied for four consecutive years in a country where English is the primary language. SAT: Not stated on the official site for non-US international applicants. The admission deadline for applicants from outside Canada is January 15 (major entrance scholarship deadline January 21), and supporting documents are due by March 1.", "sources": ["https://www.mcgill.ca/undergraduate-admissions/node/692"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 125.", "deadlines": "Applicants from outside Canada: January 15 (supporting documents by March 1)"}'::jsonb,'https://www.mcgill.ca/undergraduate-admissions/node/692'),
('ec878c05-ccde-4f52-b45d-64d51c0b2550','{"ug": "UManitoba accepts the WASSCE from the West African Examinations Council: for University 1 it asks for an equivalent minimum average of C5 (70%) over English (or first-language literature), Mathematics and two other academic senior-level courses, and some programs set other grade levels. Ghana is on the list of countries exempt from the English requirement; otherwise undergraduate minimums are IELTS Academic 6.5 (6.0 per module), TOEFL iBT 86 (tests before Jan 2026) and Duolingo 120. SAT: Not stated on the official site. Applications for fall must reach UM by March 1 to be considered for the general entrance scholarship; a separate fall admission deadline was not found on the pages read.", "sources": ["https://www.umanitoba.ca/explore/undergraduate-admissions/requirements/international-admission-requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "March 1 (application deadline for general entrance scholarship consideration)"}'::jsonb,'https://www.umanitoba.ca/explore/undergraduate-admissions/requirements/international-admission-requirements'),
('a1fa6a18-6be6-4ddc-a20f-9d42aa3ba4f7','{"ug": "Bishop''s asks international high school applicants to have normally finished 12 years of formal schooling with a credential that gives university access in their country, and reviews minimum averages case by case; WASSCE/WAEC is not named on the official site. Business needs Grade 11 maths, and B.Sc. Science needs university-entrance maths and two sciences. English minimums for undergraduate: IELTS Academic 6.5 (no component below 6.0), TOEFL iBT 90 (tests before Jan 21, 2026; no component below 20), Duolingo 115; three years of secondary schooling taught in English can exempt you. SAT: Not stated on the official site. Files are reviewed on a rolling basis; the entrance scholarship deadline for Fall 2027 is March 31.", "sources": ["https://www.ubishops.ca/admissions/admission-requirements/international-high-school-students/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 115.", "deadlines": "Rolling admission; entrance scholarship deadline for Fall 2027: March 31, 2027"}'::jsonb,'https://www.ubishops.ca/admissions/admission-requirements/international-high-school-students/'),
('db725d76-0aa4-4781-b3bf-c0ee4a1b510b','{"ug": "INRS is a French-language research institute for graduate studies (master''s and PhD) only; the official site lists no undergraduate programs, so WASSCE results do not apply. Graduate applicants who have not studied in French need French at CEFR B2; applicants without French may be admitted with working English shown by an English-language university degree or B2 English (TOEFL iBT 72, IELTS Academic 5.5). SAT: not applicable. Deadlines: Not stated on the official site pages read.", "sources": ["https://inrs.ca/en/studies/registrars-office/inrs-language-requirements/"], "deadlines": "Not stated on the pages read."}'::jsonb,'https://inrs.ca/en/studies/registrars-office/inrs-language-requirements/'),
('37fd285e-a0cf-4c17-9ea9-a401b84eea63','{"ug": "NSCAD''s official pages do not say whether WASSCE results are accepted or what grades are needed (Not stated on the official site). English minimums for undergraduate: TOEFL 90 (no part below 20) and IELTS 6.5 (no band below 6.0); Duolingo is not listed. The test is needed only if you did not have at least three years of high school taught in English, and a conditional offer is possible. SAT: Not stated on the official site. Applying by March 1 gives automatic consideration for entrance awards; a separate fall admission deadline was not found on the pages read.", "sources": ["https://nscad.ca/?p=553"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90.", "deadlines": "March 1 (admission application date for entrance award consideration)"}'::jsonb,'https://nscad.ca/?p=553'),
('2cdbde41-b2bf-4824-baa6-325c17a2f374','{"ug": "TRU says all programs require completion of secondary school and applicants must be at least 17; WASSCE minimum grades are Not stated on the official site. Undergraduates need IELTS 6.5 (no band below 6.0), TOEFL iBT 88 (no section below 20) or 4.5 on the new 2026 scale, or Duolingo 125 (no subscore below 115); Ghana is listed among countries that do not need extra English testing, and African applicants with an A or B in English on WAEC may have the test waived. SAT: Not stated on the official site. The general fall (September) deadline for international students is May 1, with earlier dates for some programs such as Nursing (January 15).", "sources": ["https://www.tru.ca/future/admissions/international/admission-requirements.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 125.", "deadlines": "Fall (September): May 1 general deadline for international students (late applications considered if space allows; busy programs may close early). Program-specific: Bachelor of Science in Nursing January 15, Juris Doctor February 1, Engineering Transfer March 1."}'::jsonb,'https://www.tru.ca/future/admissions/international/admission-requirements.html'),
('94914e67-2f14-43f0-bda1-7a80fa94a81c','{"ug": "UQO teaches in French, and it says good French is essential for admission to any program; undergraduates without an exemption must pass its SEL-B French test during their first term. Whether the WASSCE qualifies you is decided with UQO''s guide to foreign diplomas; Ghana-specific rules and minimum grades are Not stated on the official site pages that could be read. IELTS, TOEFL, Duolingo and SAT are not mentioned. For international students the fall deadline is March 1 (it can vary by program), and applications open October 1.", "sources": ["https://uqo.ca/etudiants/admission-etudiants-internationaux"], "deadlines": "Fall: international applications open October 1 and close March 1 (can vary by program and level); international deadlines close earlier than domestic ones."}'::jsonb,'https://uqo.ca/etudiants/admission-etudiants-internationaux'),
('684f3c84-e5ea-4354-aa6f-88ff6a4fb907','{"ug": "For Ghana, UVic''s minimum requirement is the Senior Secondary Certificate Examinations together with a university entrance exam; minimum grades and subjects are Not stated on the official site. SAT, ACT or AP results are accepted in place of university entrance exams, so the SAT is optional rather than required. Regular admission needs IELTS Academic 6.5 (6.0 per part), TOEFL iBT 88 (20 per section) or Duolingo 120 (no subscore below 110). International applications for September 2027 are accepted from September 1 to January 31.", "sources": ["https://www.uvic.ca/undergraduate/admissions/how-to-apply/minimum-admission-requirements-for-international-students/index.php"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 120.", "deadlines": "Fall 2027: apply September 1 to January 31; decisions November to April; accept offer by May 1; specific-criteria entrance scholarships February 15 to April 30; residence guarantee needs admission application by January 31 and residence application by February 15."}'::jsonb,'https://www.uvic.ca/undergraduate/admissions/how-to-apply/minimum-admission-requirements-for-international-students/index.php'),
('02422147-3142-4dd4-82e0-05ef9cd049bb','{"ug": "McMaster lists WAEC results under its international curriculum requirements: five Senior Secondary 3 subjects including all prerequisites for the chosen program, with SS1, SS2 and first-term SS3 transcripts; the minimum average varies by program and no minimum subject grade is stated. Undergraduate English minimums are IELTS Academic 6.5 overall (6.0 in each band), TOEFL iBT 86 (20 per section; 4.5 on the new 2026 scale) and Duolingo 120. SAT/ACT is described as optional only for American-style curriculum applicants; it is not stated for WAEC applicants. The fall application deadline is not stated on the page read; McMaster points to a deadline search tool.", "sources": ["https://future.mcmaster.ca/apply/curriculum-requirements/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://future.mcmaster.ca/apply/curriculum-requirements/'),
('44b13810-abb8-45f8-a343-d738e56c03e4','{"ug": "uOttawa has a Ghana page: you need the WASSCE (completed or in progress) with a minimum average of 75% (B3), higher for some programs, plus the prerequisites for your chosen program. Undergraduate English minimums are IELTS Academic 6.5 (writing 6.5), TOEFL iBT 86 (writing 22) and Duolingo 120 (literacy 120); no country-based exemption is stated. SAT policy is not stated on the official site. The general fall application deadline is not stated on the pages read; for the English scholarships the page said to apply by March 1 (2025 cycle shown).", "sources": ["https://www.uottawa.ca/study/undergraduate-studies/international-applicants/ghana"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Not stated generally; scholarship page (2025 cycle) asked for admission applications by March 1 and processing by March 15"}'::jsonb,'https://www.uottawa.ca/study/undergraduate-studies/international-applicants/ghana'),
('b5b26aa9-7174-4289-a4b3-02ce977d868d','{"ug": "Brandon accepts the WASSCE: C5 or higher in at least five subjects, including English and Mathematics. Undergraduate English minimums are IELTS Academic 6.5 (6.0 per band), TOEFL iBT 86 (20 per section; 4.5 on the new scale from 21 Jan 2026) and Duolingo 120 (105 per component); the English page also lists WASSCE with C4 or higher in English Language as a qualifying exam. SAT policy is not stated on the official site. The fall (September) deadline for both the application and official documents is April 1; later files are considered for January.", "sources": ["https://www.brandonu.ca/future-students/apply/international/requirements/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Fall (September): April 1 for application and official documents"}'::jsonb,'https://www.brandonu.ca/future-students/apply/international/requirements/'),
('bc5ef839-6d38-44be-be78-2f4e3ee46a60','{"ug": "KPU''s Africa page says applicants from WAEC/NECO countries need Grade C4 in English; undergraduate applicants must have graduated from high school (or have 9+ university credits) and meet program-specific requirements, with no minimum average stated. Undergraduate English minimums are IELTS Academic 6.5 (6.0 per band), TOEFL iBT 88 (no sub-score below 20) and Duolingo 110. SAT is not mentioned on the official site. KPU does not accept late applications, but the fall deadline was not stated on the pages that could be read.", "sources": ["https://www.kpu.ca/international/Africa"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 110.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.kpu.ca/international/Africa'),
('a0208ac5-9d8e-4e3b-89f2-2b535aed71ca','{"ug": "OCAD U does not mention WAEC/WASSCE specifically; international high school applicants need an overall final-year average of B (70%) and English at B (70%), plus a portfolio for studio BFA/BDes programs (a writing sample for the BA in Visual and Critical Studies). Undergraduate English minimums are IELTS Academic 6.5 (6.0 per part), TOEFL iBT 84 (4.5 on the new scale from 21 Jan 2026) and Duolingo 110; Ghana is on the list of countries where four years of English-medium study may give an exemption, but this is not automatic. SAT policy is not stated on the official site. For Fall 2027, the deadline for non-Ontario applicants is February 1, 2027, with portfolios due February 10, 2027.", "sources": ["https://admissions.ocadu.ca/apply/academic-requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 84, Duolingo 110.", "deadlines": "Fall 2027: apply by February 1, 2027 (Group B, all other applicants); portfolio by February 10, 2027"}'::jsonb,'https://admissions.ocadu.ca/apply/academic-requirements'),
('88bcb3aa-6b5c-442b-8f0e-d800ff050d32','{"ug": "Trent''s requirements-by-country page asks Ghanaian applicants for grade 10-12 transcripts and WAEC exam results, with a minimum grade of B3. Undergraduate English minimums are IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 86 (writing 20; 4.5 on the new 2026 scale) and Duolingo 115; three years of English-only high school without ESL may give an exemption, and English proof is due by July 1 for September entry if required. SAT is only recommended for United States applicants; it is not stated for Ghana. The general fall application deadline is not stated on the official pages read; scholarship applications close February 15.", "sources": ["https://www.trentu.ca/international/node/148"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 115.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.trentu.ca/international/node/148'),
('3eb529d0-4129-453f-8ec4-29ca24578bbd','{"ug": "Université Sainte-Anne is a French-language university; its official pages do not state WASSCE/WAEC requirements, a minimum average for international applicants, or language test minimums (IELTS, TOEFL, Duolingo, or a French test) - admission criteria are listed per program. SAT is not mentioned on the official site. International applications for the fall session must be submitted before May 1 of the same year (winter: before August 1 of the previous year), with a $150 application fee.", "sources": ["https://www.usainteanne.ca/futurs-etudiants/demande-dadmission"], "deadlines": "Fall: before May 1 of the same year (international students)"}'::jsonb,'https://www.usainteanne.ca/futurs-etudiants/demande-dadmission'),
('f22c4c6d-2d8f-44e9-806e-ae9acbe47ce7','{"ug": "UWindsor''s undergraduate admission page lists WAEC requirements only for Nigeria (B3 minimum average in the top five academic subjects including English); Ghana and the WASSCE are not named, so the requirement for Ghanaian applicants is not stated on the official site. The same page lists TOEFL iBT 83 (writing 20) and Duolingo 115 for undergraduates; no IELTS minimum is stated, and you do not need to meet the English requirement when you apply (conditional offers with an English pathway are possible). SAT is stated as not required only for US applicants. The recommended deadline for September (fall) admission is May 1, with later applications considered if space allows.", "sources": ["https://www.uwindsor.ca/registrar/node/498"], "english": "Undergraduate minimums: TOEFL iBT 83, Duolingo 115.", "deadlines": "Fall (September): recommended deadline May 1; later applications considered if space remains"}'::jsonb,'https://www.uwindsor.ca/registrar/node/498'),
('dc76ebd7-662f-444c-b60b-2b64ee8349d0','{"ug": "Queen''s has a WASSCE page: grades needed vary by program and year, with the competitive range at a combination of B2 and B3, plus program subjects (for example English, Mathematics, Chemistry and Physics for Engineering; B2 in English and Mathematics for Commerce). Undergraduate English minimums are IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (20 per section, before Jan 2026; 4.5 on the new scale) and Duolingo 120; three recent years of English-medium schooling or living in an English-speaking country can exempt you. SAT policy is not stated for WASSCE applicants. For Fall 2027 apply by March 1, 2027 (February 1 for Commerce, Health Sciences and Nursing), with all documents and English scores by March 31, 2027.", "sources": ["https://www.queensu.ca/admission/applying/admission-requirements/wassce-west-african-senior-school-certificate-"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 120.", "deadlines": "Fall 2027: March 1, 2027 (Feb 1, 2027 for Commerce, Health Sciences, Nursing; supplementary application Feb 15); documents by March 31, 2027"}'::jsonb,'https://www.queensu.ca/admission/applying/admission-requirements/wassce-west-african-senior-school-certificate-'),
('7cd9cb27-27e4-431b-ad9a-e03b10823242','{"ug": "USask says it can check WAEC results online for applicants from Ghana and Nigeria (you upload your WAEC exam number, year and scratch card/e-PIN), but minimum WASSCE grades and subjects are shown only through an interactive requirements tool and are not stated on the pages read. Undergraduate English minimums are IELTS Academic 6.5 (no band below 6), TOEFL iBT 86 (19 per part, old scale; 4.5 on the new scale) and Duolingo 120 (100 per area, from Jan 2026). SAT is not mentioned on the official site. The general fall deadline is not stated on the pages read; applying by February 15 is required for the international entrance awards.", "sources": ["https://admissions.usask.ca/requirements/apply.php"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 120.", "deadlines": "Not stated generally; apply by February 15 to be considered for international entrance awards"}'::jsonb,'https://admissions.usask.ca/requirements/apply.php'),
('7bf7b280-9003-4b55-a54e-a544ed3b0fc3','{"ug": "Brock accepts the Ghana Senior Secondary School Certificate (WAEC) with at least 6 subjects and a minimum overall average of C4 for admission consideration. Ghana is on Brock''s list of English-exempt countries; otherwise undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (no band below 21) or Duolingo 110. The SAT is not required; Brock says SAT scores can help in borderline cases. For Fall 2026 the international application deadline was January 15, 2026 (later applications may be accepted if space allows), with February 1 supplementary deadlines for some programs.", "sources": ["https://brocku.ca/admissions/international/requirements-by-country/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 110.", "deadlines": "Fall 2026: January 15, 2026 for international applicants not at an Ontario high school; February 1, 2026 supplementary deadlines for Visual Arts, Game Design/Programming and Accelerated Mathematics. Fall 2027 dates not yet published on the page read."}'::jsonb,'https://brocku.ca/admissions/international/requirements-by-country/'),
('a61a464c-6cb5-49e5-997b-1d7018f41641','{"ug": "Lakehead''s Ghana and Nigeria page says it considers applicants with the Senior Secondary Certificate Examinations or the Senior School Certificate with WAEC results, which must come directly from WAEC or be verifiable with a WAEC scratch-card PIN; no minimum grades or subjects are stated. Most undergraduate programs need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 80 (no part below 19) or 4.5 on the new scale, or Duolingo 120 (no subscore below 115); three years of full-time high school taught in English can also meet the requirement. Nursing, Juris Doctor and the two-year B.Ed. need IELTS 7.0 or TOEFL 103. SAT policy and the fall application deadline: Not stated on the official site.", "sources": ["https://www.lakeheadu.ca/future-students/admissions/undergraduate/international-student/requirements-by-country/ghana-and-nigeria"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 80, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.lakeheadu.ca/future-students/admissions/undergraduate/international-student/requirements-by-country/ghana-and-nigeria'),
('f6203b95-163f-4a3c-814f-0dea05945d49','{"ug": "Ontario Tech asks Ghanaian applicants for all Senior Secondary grades including WASSCE results (shared through the WAEC digital certificate service), and mock exam results if still in school; no minimum grades are stated. English minimums are IELTS Academic 6.5 (no part below 6.0; 7.0 for Education and Nursing), TOEFL iBT 4.5 on the new scale (no section below 4.0) and Duolingo 120 (130 for Education and Nursing). SAT is mentioned only for US-patterned applicants, not for Ghana. For fall entry, early programs (Nursing, Medical Laboratory Science) close January 29 and all other programs March 31 for equal consideration; later applications are still processed.", "sources": ["https://admissions.ontariotechu.ca/applicant-information/international-admission-requirements.php"], "english": "Undergraduate minimums: IELTS 6.5, Duolingo 120.", "deadlines": "Fall 2027: January 29 for Nursing and Medical Laboratory Science; March 31 for all other programs (equal consideration)"}'::jsonb,'https://admissions.ontariotechu.ca/applicant-information/international-admission-requirements.php'),
('6e513a92-f6f4-4b57-8d66-36dd5be5be0f','{"ug": "Université de Moncton is a French-language university; its international admission page does not list Ghana (applicants use the ''other countries'' document list) and does not state WASSCE grades, language test minimums or SAT policy. Its general undergraduate conditions are a high school diploma with a minimum 70% average across five courses used for admission, plus program-specific requirements. International applications for the fall session are due by May 31 (applications may close earlier if demand is high); the application fee is $300.", "sources": ["https://www.umoncton.ca/processus-d%E2%80%99admission-pour-%C3%A9tudiants-internationaux"], "deadlines": "Fall: by May 31 for international students (undergraduate and graduate); may close earlier"}'::jsonb,'https://www.umoncton.ca/processus-d%E2%80%99admission-pour-%C3%A9tudiants-internationaux'),
('673178d4-a435-458e-85a1-05f5f6b0080f','{"ug": "TELUQ is a French-language distance (online) university. It accepts applications at any time (continuous admission), but its current fall deadline is Not stated on the official site pages that could be read. WASSCE acceptance and grades, French or English test minimums and SAT policy are Not stated on the official site pages that could be read.", "sources": ["https://www.teluq.ca/site/admission/dates_importantes.php"], "deadlines": "Continuous admission (applications received at any time); the dates page only showed an old (2018) fall cycle, so no current fall deadline is recorded."}'::jsonb,'https://www.teluq.ca/site/admission/dates_importantes.php'),
('3f7a27fb-5ed2-42f7-b5bc-33f873ea637d','{"ug": "VIU accepts the West African Senior School Certificate from Ghana as equivalent to high school completion, but minimum WASSCE grades are not stated on the official site. Ghana is on VIU''s list of countries whose high school diploma exempts applicants from an English test; otherwise undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (no section below 20, tests before Jan 21, 2026) or Duolingo 115 (no band below 105). SAT: Not stated on the official site. A fall application deadline is not stated on the general international admissions page; check the program page.", "sources": ["https://www.viu.ca/admissions/international"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 115.", "deadlines": "Not stated on the general international admissions page (check program page). International Student Entrance Scholarship applications close February 28, 2027."}'::jsonb,'https://www.viu.ca/admissions/international'),
('ebe01186-bdc6-419d-a8d2-413ed97e168d','{"ug": "SFU lists Ghana among its international high school countries, but the Ghana-specific WASSCE grade requirements could not be read; basic rules ask for graduation from a university-preparatory senior high school program, with a minimum C-/60% in an acceptable Math course, and the average is calculated from final-year results. English minimums for undergraduates: IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (no part below 20; for tests from 21 January 2026 the new-scale score is 4.5, no part below 4.0), Duolingo 125. SAT: Not stated on the official site. For Fall 2027 the application deadline is 31 January 2027, and documents are due 28 February 2027.", "sources": ["https://www.sfu.ca/students/admission/admission-requirements/international-highschool/country/basic-requirements.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 125.", "deadlines": "Fall 2027: apply by January 31, 2027; documents by February 28, 2027"}'::jsonb,'https://www.sfu.ca/students/admission/admission-requirements/international-highschool/country/basic-requirements.html'),
('f6fa150f-e620-4559-b69e-5d50cae8aebb','{"ug": "U of T accepts the West African Examinations Council Senior School Certificate Examination (WASSCE) for applicants from Ghana; its country page lists no specific minimum grades or subjects, and Engineering has its own requirements. English minimums (from the U of T Mississauga page): IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 89 with 22 in Speaking and Writing (or 4.5 on the new scale for tests from 21 January 2026), Duolingo 120. SAT: Not stated on the official site for Ghanaian applicants. For Fall 2027 the recommended date to apply is 7 November and the final deadline is 15 January for most programs (Medical Radiation Sciences: 1 February).", "sources": ["https://future.utoronto.ca/international-high-school-requirements-country?page=2"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 89, Duolingo 120.", "deadlines": "Fall 2027: recommended by November 7; final deadline January 15 for most programs (Medical Radiation Sciences February 1); documents by February 1 for most programs (January 15 for Engineering and Music)"}'::jsonb,'https://future.utoronto.ca/international-high-school-requirements-country?page=2'),
('325fa582-624c-4e07-8f75-0a3a94be267b','{"ug": "CBU has a country-specific requirements page, but its Ghana/WASSCE rules could not be read, so the WASSCE minimums are not stated here. English minimums for undergraduates: IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 80 (no score below 20, for tests before 21 January 2026), Duolingo 120 (no score below 105); at least two years of secondary school recognized by CBU can exempt you. SAT: Not stated on the official site. For September 2027, international undergraduate applications open 1 October 2026 and close 15 May 2027, or earlier if seats fill.", "sources": ["https://www.cbu.ca/future-students/admissions/admission-requirements/international-admissions/language-requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 80, Duolingo 120.", "deadlines": "September 2027: applications open October 1, 2026 and close May 15, 2027 (may close early if seats fill)"}'::jsonb,'https://www.cbu.ca/future-students/admissions/admission-requirements/international-admissions/language-requirements'),
('c0dae375-b222-4ebe-a687-3a290bdef5ad','{"ug": "Laurentian accepts Ghana''s WASSCE, verified online through WAEC Direct, with a minimum average of C4 or better, and lists English as exempt for Ghanaian applicants. Programs also need senior-level subjects, for example English and Math for Business, and English, Math, Physics and Chemistry for Engineering. If a test is needed, the minimums are IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (tests before 2026), and Duolingo 120 (no subscore below 110). SAT: Not stated on the official site. Fall application deadline: Not stated on the official site.", "sources": ["https://laurentian.ca/academics/admissions/international/undergraduate-admissions"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://laurentian.ca/academics/admissions/international/undergraduate-admissions'),
('843e636b-f7a0-4029-9485-5b18e245469e','{"ug": "Polytechnique Montréal teaches in French. Applicants with foreign secondary diplomas such as Ghana''s WASSCE are assessed case by case, and no WASSCE grades or subjects are listed. Applicants must meet the French language requirement, for example DELF B2, DALF C1, or TCF/TEF Canada B2 (400) in each part; English tests (IELTS, TOEFL, Duolingo) are not used for admission. SAT: Not stated on the official site. Fall application deadline: Not stated on the official site (a separate deadlines page exists).", "sources": ["https://www.polymtl.ca/admission/baccalaureat/conditions-dadmission-au-baccalaureat/exigences-academiques/2-etudes-hors-quebec/214-autres-diplomes"], "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.polymtl.ca/admission/baccalaureat/conditions-dadmission-au-baccalaureat/exigences-academiques/2-etudes-hors-quebec/214-autres-diplomes'),
('11348a9e-21f4-4637-904a-7958fd445599','{"ug": "Université de Saint-Boniface is a French-language university in Manitoba. Applicants who finished high school outside Canada are checked against an equivalencies-by-country list, but the Ghana/WASSCE requirements are not stated on the pages read. English test results (IELTS, TOEFL, Duolingo) are required only for some programs such as Nursing and Social Work, and the minimum scores are not stated on the pages read; new students take a French placement test, which is not an admission test. SAT: Not stated on the official site. Fall application deadline for international students: Not stated on the official site.", "sources": ["https://ustboniface.ca/en/admissions"], "deadlines": "Not stated on the pages read."}'::jsonb,'https://ustboniface.ca/en/admissions'),
('df8e11c2-7f3a-43e2-b8ca-cf3e44a74c1b','{"ug": "Guelph accepts WAEC results from Ghana with a minimum of B3 on predicted grades, and a scratch card is needed to confirm final results; required subjects depend on the program (for example English, Math, Biology or Chemistry). English minimums: IELTS Academic 6.5 (no band below 6), TOEFL iBT 89 (no score below 21; 4.5 on the new scale from 21 January 2026), Duolingo 110. SAT/ACT is optional for the fall 2027 cycle, and there is no penalty for not submitting a score. For Fall 2027, high school applicants studying outside Canada apply by 15 May (documents by 22 May); Landscape Architecture closes 1 February.", "sources": ["https://www.uoguelph.ca/admission/undergraduate/international/requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 89, Duolingo 110.", "deadlines": "Fall 2027: apply by May 15, 2027 (Landscape Architecture February 1); documents by May 22, 2027"}'::jsonb,'https://www.uoguelph.ca/admission/undergraduate/international/requirements'),
('663200da-f3f7-4c42-bf27-e2ace87fe988','{"ug": "Laurier accepts WAEC/WASSCE results (or SS3 grades in progress) and calculates your average from five academic subjects including English; it converts grades as A1=95%, B2=85%, B3=75%, C4=70%, C5=65% and C6=60%, but sets no single minimum grade. Program subjects (Math, Biology, Chemistry, Physics) vary, and you will need final certificates plus unused scratch card details. English minimums: IELTS Academic 6.5 (each band 6.0), TOEFL iBT 83 (each part 20; 4.5 on the new scale from January 2026), Duolingo 120; three years of full-time English-medium schooling may exempt you. SAT: Not stated on the official site. The application deadline for Fall 2027 is 1 April 2027.", "sources": ["https://wlu.ca/future-students/undergraduate/admissions/assets/resources/requirements-by-country/africa/waec.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 120.", "deadlines": "Fall 2027: apply by April 1, 2027"}'::jsonb,'https://wlu.ca/future-students/undergraduate/admissions/assets/resources/requirements-by-country/africa/waec.html'),
('09d436f1-10b1-44dc-aeb2-8864ad3f8cf8','{"ug": "UBC lists Ghana on its international high school requirements page, but the Ghana/WASSCE grade and subject rules load dynamically and could not be read, so the minimums are not stated here. English minimums (Vancouver): IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 90 (Reading 22, Listening 22, Writing 21, Speaking 21), Duolingo 125 (subscores 115 to 120). SAT: Not stated on the official site. For the 2027 Winter Session (September 2027), apply by 15 January 2027; high school applicants from outside Canada submit documents by 15 March 2027, and English proof is due 15 February 2027.", "sources": ["https://you.ubc.ca/applying-ubc/requirements/international-high-schools/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 125.", "deadlines": "September 2027 entry: apply by January 15, 2027 (December 2, 2026 for International Scholars Program applicants); documents by March 15, 2027"}'::jsonb,'https://you.ubc.ca/applying-ubc/requirements/international-high-schools/'),
('4648d072-a5b2-4f43-90a4-59b46c255646','{"ug": "Waterloo lists ''West African Examination Council (WAEC)'' as a recognised system of study, but minimum WASSCE grades are not stated on the official pages reviewed. Undergraduates need IELTS Academic 6.5 (6.5 in writing and speaking, 6.0 in reading and listening), TOEFL iBT 90 (25 writing, 25 speaking, tests before Jan 21, 2026) or Duolingo 120 (Literacy and Production 125); the test can be waived if your last four years of full-time study were entirely in English. SAT: Not stated on the official site. For Fall 2027 the application deadline is February 1, 2027 (January 15 for Engineering), with documents due February 15, 2027 (February 1 for Engineering).", "sources": ["https://uwaterloo.ca/future-students/admissions/english-language-requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 90, Duolingo 120.", "deadlines": "Fall 2027: apply by February 1, 2027 (Engineering January 15, 2027); documents by February 15, 2027 (Engineering February 1, 2027)."}'::jsonb,'https://uwaterloo.ca/future-students/admissions/english-language-requirements'),
('f9ea13d7-066f-4a6b-a2d8-dca321f7487d','{"ug": "WASSCE/WAEC acceptance and minimum grades: Not stated on the official site pages reviewed (CapU points to a Secondary School Equivalencies list). Ghana is on CapU''s list of countries where four years of full-time study in English meets the English requirement; otherwise Fall 2027 undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL 83 (tests before Jan 21, 2026) or Duolingo 120 (no sub-score below 110). SAT: Not stated on the official site. Program deadlines are listed on each program page; to get the international entrance award for Fall 2027 you must apply by November 30, 2026.", "sources": ["https://capilanou.ca/admissions/apply-to-capu/admission-requirements/english-language-requirements"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 120.", "deadlines": "Program application deadlines are on each program page (not stated on general pages). For the International Entrance & Performance Award, Fall 2027: apply by November 30, 2026, deposit by December 4, 2026, study permit submitted by December 31, 2026."}'::jsonb,'https://capilanou.ca/admissions/apply-to-capu/admission-requirements/english-language-requirements'),
('5928c28e-2d61-409e-9cd0-8a903a57432c','{"ug": "WASSCE/WAEC acceptance and minimum grades: Not stated on the official site; requirements vary by program. Undergraduates need IELTS Academic 6.5 (5.5 in each band), TOEFL iBT 86 (tests before Jan 21, 2026) or Duolingo 115, unless English is your primary language (based on the language of instruction in your last three years of study and at home). SAT: Not stated on the official site. International applicants must apply by May 1 for Fall intake unless the program has an earlier date (some degrees, such as Nursing and Social Work, close March 30), and must apply by March 1 to be considered for entrance scholarships.", "sources": ["https://www.macewan.ca/ELP"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 86, Duolingo 115.", "deadlines": "International applicants: May 1 for Fall intake unless an earlier program date applies (e.g. March 30 for BScN, Psychiatric Nursing, Social Work, Public Safety and Justice, PE Transfer). Final documents due August 1. Entrance scholarship consideration: apply for admission by March 1 (Fall) or July 1 (Winter)."}'::jsonb,'https://www.macewan.ca/ELP'),
('a9e92987-4bc9-4cc7-a5e9-6d126d3e6b02','{"ug": "RMC undergraduate degrees are open only to officer cadets and other Canadian Armed Forces or federal defence routes; the main route (the Regular Officer Training Plan) requires applicants to be a Canadian citizen or permanent resident, so a Ghanaian applicant cannot normally apply for a bachelor''s degree. WASSCE/WAEC acceptance, IELTS/TOEFL/Duolingo minimums and SAT policy: Not stated on the official site. The ROTP application deadline is January 31 of the year of enrolment. Some graduate programmes may admit civilians.", "sources": ["https://extlin9.rmc.ca/en/node/416"], "deadlines": "ROTP: January 31 of the year of enrolment (later applications may be considered depending on availability)."}'::jsonb,'https://extlin9.rmc.ca/en/node/416'),
('15fbcbf2-bf3f-4eea-9c88-c2e7e15bd68a','{"ug": "Sherbrooke teaches in French and requires 13 years of schooling for bachelor''s admission, so a WASSCE holder will likely need extra post-secondary study; Ghana/WAEC and minimum WASSCE grades are not stated on the official site. Non-francophone applicants must prove French at the CEFR level set by each program (B2 to C2 in all four skills) with DELF/DALF, TCF, TEF or Test Bright; the TFI is not accepted. IELTS/TOEFL/Duolingo minimums and SAT: Not stated on the official site. The undergraduate deadline for international applicants for the autumn term is January 15 (some programs differ).", "sources": ["https://www.usherbrooke.ca/admission/da/valider-admissibilite/equivalences-internationales"], "deadlines": "Undergraduate, international applicants: January 15 for the autumn term (some programs set their own dates)."}'::jsonb,'https://www.usherbrooke.ca/admission/da/valider-admissibilite/equivalences-internationales'),
('524f5f1c-ee49-471e-ad25-8c4cff67313e','{"ug": "Lethbridge accepts the Ghana Senior School Certificate (official WAEC or NECO results) with credit passes or better in English and at least four other subjects. Undergraduates need IELTS Academic 6.0 (6.0 in each band), TOEFL iBT 80 (Listening, Reading and Speaking 16, Writing 18) or Duolingo 105; three years of full-time secondary study in English in a recognised country can also meet the requirement. SAT: not named on the official site, though a ''Standardized Test Admission route'' exists for applicants who do not meet the general requirements. Fall deadline: Not stated on the pages reviewed; apply by December 15 for automatic Board of Governors'' scholarship consideration.", "sources": ["https://ulethbridge.ca/ross/admissions/undergrad/international/intreq_table"], "english": "Undergraduate minimums: IELTS 6.0, TOEFL iBT 80, Duolingo 105.", "deadlines": "Fall application deadline not stated on pages reviewed. Award deadlines (2026 cycle): International Students Entrance Scholarship March 15; Dhillon School of Business International Award June 15; admission application before December 15 for Board of Governors'' Admission Scholarship."}'::jsonb,'https://ulethbridge.ca/ross/admissions/undergrad/international/intreq_table'),
('56e317bc-8ad5-4be1-a748-3614e352c65a','{"ug": "WASSCE/WAEC acceptance and minimum grades: Not stated on the official site; for the Business Administration degree international applicants need English 12 (65%) and Math 11 or equivalents, which can be assessed from an evaluated transcript (e.g. IQAS). The Business Administration degree requires IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 87 (no section below 20) or Duolingo 120 (with subscores); Ghana is not on the English-test exemption list. SAT: Not stated on the official site. For Fall 2027, international applications are open October 1, 2026 to April 1, 2027.", "sources": ["https://yukonu.ca/international/future-students/admission"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 87, Duolingo 120.", "deadlines": "Fall 2027 international intake: applications open October 1, 2026 and close April 1, 2027; deferral deadline August 1, 2027."}'::jsonb,'https://yukonu.ca/international/future-students/admission'),
('d421e3c2-fb47-4406-b709-45b387aa3328','{"ug": "TMU lists the West African Examinations Council Senior School Certificate Examination as the qualification it reviews for applicants from Ghana; minimum grades and subjects for WASSCE are not stated on the official site. Undergraduate English minimums are IELTS Academic 6.5 overall, Duolingo 120, and TOEFL iBT 83 (Engineering and most Science) or 92 (all other programs) for tests taken before January 21, 2026. SAT policy is not stated on the official site. Complete Fall 2027 applications received by February 1, 2027 get equal consideration; programs may close earlier if full.", "sources": ["https://www.torontomu.ca/admissions/undergraduate/requirements/international/country-specific/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 92, Duolingo 120.", "deadlines": "Fall 2027: complete applications by February 1, 2027 receive equal consideration; programs may close earlier due to space."}'::jsonb,'https://www.torontomu.ca/admissions/undergraduate/requirements/international/country-specific/'),
('3306b401-6559-4bf0-a40e-9c61f976c9bd','{"ug": "Western has a Ghana requirements page for students whose secondary school is recognized by the Ministry of Education, but WASSCE minimum grades and subjects could not be confirmed from the official site. Undergraduate English minimums are IELTS Academic 6.5 overall, Duolingo 115, and TOEFL iBT 83 for tests taken before January 21, 2026. SAT policy is not stated on the official site. Fall application deadline is not stated on the official pages reviewed.", "sources": ["https://welcome.uwo.ca/next-steps/requirements/international-high-school/index.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 115.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://welcome.uwo.ca/next-steps/requirements/international-high-school/index.html'),
('2589b475-101d-4c24-a502-dcdfdf0c1810','{"ug": "ÉTS is a French-language engineering school; whether WASSCE/WAEC results are accepted for bachelor''s entry is not stated on the official site, and admission conditions are set per program on each program fact sheet. Bachelor''s applicants with studies outside Québec must provide transcripts, a CV, a birth certificate and proof of meeting the French language requirement. English test minimums (IELTS, TOEFL, Duolingo) for bachelor''s programs are not stated on the official site, and SAT is not mentioned. The fall application deadline for international students is March 1.", "sources": ["https://www.etsmtl.ca/en/study-at-ets/applying-to-ets"], "deadlines": "Fall: March 1 for international students."}'::jsonb,'https://www.etsmtl.ca/en/study-at-ets/applying-to-ets'),
('e8930518-f9f3-4a63-a77d-230467e237f9','{"ug": "Memorial accepts the WAEC Senior Secondary Certificate with five subjects including English, Mathematics, a laboratory science (Biology, Chemistry or Physics; Integrated Science not accepted) and electives, with a minimum average of C4 in the required subjects and a pass in each. Two years of study in this curriculum normally removes the need for a separate English test. Otherwise the undergraduate minimums are IELTS Academic 6.5 (6 in reading and writing), TOEFL iBT 83 (tests up to January 2026) and Duolingo 115. SAT is not mentioned on the official site. For fall, the priority deadline is March 1 (also the date to be considered for early entrance scholarships) and applications close September 9.", "sources": ["https://www.mun.ca/undergrad/admissions/i-want-to-apply/international-high-school-curriculum-requirements/west-african-examinations-council-waec-or-nation/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 115.", "deadlines": "Fall: priority deadline March 1 (early entrance scholarship consideration); documents by August 20; applications close September 9."}'::jsonb,'https://www.mun.ca/undergrad/admissions/i-want-to-apply/international-high-school-curriculum-requirements/west-african-examinations-council-waec-or-nation/'),
('a01a23d1-90ee-49d2-b812-07a537408e97','{"ug": "Whether WASSCE/WAEC results are accepted, and what grades are needed, is not stated on the official site; admission requirements are listed on each program page and Royal Roads may consider non-standard qualifications under its Flexible Admission policy. For first-year undergraduate entry the English minimums are IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 88 (at least 20 in each section) and Duolingo 120. SAT policy is not stated on the official site. Fall application deadline is not stated on the official site.", "sources": ["https://www.royalroads.ca/node/368"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 120.", "deadlines": "Not stated on the pages read."}'::jsonb,'https://www.royalroads.ca/node/368'),
('94df807f-9cdd-44df-9b7e-8db7da679fb2','{"ug": "UQAC is a French-language university. WASSCE/WAEC acceptance and minimum grades, French or English test minimums (IELTS/TOEFL/Duolingo), SAT policy and the fall application deadline: Not stated on the official site pages found. UQAC''s arrival guide for international students gives a fall 2026 registration deadline of August 31, 2026. Check UQAC''s admissions office directly for program requirements.", "sources": ["https://www.uqac.ca/bdi-docs/incoming/guide-premieres-demarches.pdf"], "deadlines": "Fall application deadline not stated on pages found. Registration deadline for arriving international students: August 31, 2026 (fall 2026)."}'::jsonb,'https://www.uqac.ca/bdi-docs/incoming/guide-premieres-demarches.pdf'),
('72cb9981-e655-4ffc-969c-0c0f43fa3d0e','{"ug": "UNB accepts the West African Senior School Certificate from Ghana with a minimum grade of C5 (or the older Senior Secondary School Certificate with a minimum grade of C); further Maths is required for programs that need pre-calculus. Ghana is on UNB''s English exemption list if you studied at an English-speaking high school for at least 1 year (4 years for Nursing and Health Sciences); otherwise the minimums are IELTS Academic 6.5, TOEFL iBT 85 (pre-2026 tests) and Duolingo 115. SAT policy for Ghanaian applicants is not stated on the official site. The general fall application deadline is March 31, and undergraduate scholarship applications are due March 1.", "sources": ["https://www.unb.ca//international/admission/countries.html"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 85, Duolingo 115.", "deadlines": "Fall: March 31 general application deadline (later applications accepted while seats remain); scholarship applications due March 1."}'::jsonb,'https://www.unb.ca//international/admission/countries.html'),
('0d996d07-9006-427e-b299-4b5d115e9110','{"ug": "Université de Montréal is French-language; Ghana appears on its list of foreign diploma equivalences, but WASSCE minimum grades and subjects are not stated on the official site and requirements vary by program. Applicants must show French proficiency that meets the program''s requirement; English test minimums (IELTS, TOEFL, Duolingo) are not stated on the official site. SAT is not mentioned on the official site. For fall, international bachelor''s applicants should apply by April 1 (some programs differ; the program page prevails).", "sources": ["https://admission.umontreal.ca/vous-etes/futurs-etudiants/formes-a-letranger/"], "deadlines": "Fall: by April 1 for international 1st-cycle applicants per the deadlines page (an FAQ on the official site mentions February 1); program fact sheet prevails."}'::jsonb,'https://admission.umontreal.ca/vous-etes/futurs-etudiants/formes-a-letranger/'),
('6d889f9d-d0a9-401d-9036-d238c041207e','{"ug": "York accepts WAEC examination results from Ghana, but minimum grades and required subjects are not stated on the official site (requirements vary by program). Ghana is on York''s English exemption country list for students with four full years of English-medium high school; otherwise the minimums are IELTS Academic 6.5, TOEFL iBT 88 (tests before January 2026) and Duolingo 120. SAT policy is not stated on the official site. The Fall 2027 deadline for guaranteed consideration is March 24, 2027 (Schulich BBA closes January 15, 2027).", "sources": ["https://futurestudents.yorku.ca/requirements/hs-international-countries"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 88, Duolingo 120.", "deadlines": "Fall 2027: March 24, 2027 for guaranteed consideration (Schulich BBA: January 15, 2027); some programs have earlier supplementary deadlines."}'::jsonb,'https://futurestudents.yorku.ca/requirements/hs-international-countries'),
('1edb1115-6628-4e01-b1a8-0077c83e6f0c','{"ug": "ENAP is a French-language graduate school of public administration and does not offer undergraduate entry, so WASSCE/WAEC results are not relevant; its Master''s in Public Administration requires a bachelor''s degree with a cumulative average of at least 3.2/4.3. Applicants need very good French and the ability to read English; no specific English test minimums (IELTS, TOEFL, Duolingo) are stated on the official site. SAT is not applicable/not stated. Fall applications must be submitted before April 1.", "sources": ["https://enap.ca/media/242/download"], "deadlines": "Fall: apply before April 1 (school recommends applying five months before the term)."}'::jsonb,'https://enap.ca/media/242/download'),
('8e598699-906c-4cde-8879-c27e86901921','{"ug": "Whether WASSCE/WAEC results are accepted, and with what grades, is not stated on the official site; requirements vary by country and degree. Undergraduate English minimums are IELTS Academic 6.5 (no band below 6), Duolingo 110 (with sub-score minimums) and TOEFL iBT 4.5 on the new scale; there is no Ghana-specific exemption listed. SAT policy is not stated on the official site. A fall application deadline is not stated, but applications for admission and scholarships (with all documents) are due March 1 for scholarship consideration.", "sources": ["https://www.mta.ca/requirements/"], "english": "Undergraduate minimums: IELTS 6.5, Duolingo 110.", "deadlines": "March 1: admission and scholarship application with documents for scholarship consideration; general fall deadline not stated."}'::jsonb,'https://www.mta.ca/requirements/'),
('4d3c356c-5dac-46ed-a0db-6e4259671937','{"ug": "Saint Mary''s accepts completed WAEC/WASSCE results and considers grades of C6 and higher: BA needs English plus four other academic subjects, BComm needs English, Mathematics and three others, and BSc needs English, Further Mathematics, one science and two others. SMU lists ''Test of English: not required'' for Ghana; otherwise undergraduates need IELTS Academic 6.5 (no band below 6.0), TOEFL iBT 83 (no band below 20, tests up to January 2026) or Duolingo 115 (no sub-score below 95). SAT: Not stated on the official site. Applications for 2027-28 opened October 1, 2026; a September 2027 international deadline is not stated, but apply by February 15, 2027 to be considered for entrance awards and admission scholarships.", "sources": ["https://www.smu.ca/future-students/admissions/internationaladmissions/"], "english": "Undergraduate minimums: IELTS 6.5, TOEFL iBT 83, Duolingo 115.", "deadlines": "Applications for 2027-28 open October 1, 2026. September 2027 international application deadline not stated (Winter 2027 international deadline was October 15). Entrance Awards and Admissions Scholarships deadline: February 15, 2027."}'::jsonb,'https://www.smu.ca/future-students/admissions/internationaladmissions/'),
('c3742177-137c-4914-b402-649dfb30de01','{"ug": "UQAM teaches in French; bachelor''s admission requires a diploma obtained after 13 years of schooling (or a French baccalauréat), and a 4-year management bachelor''s with a preparatory year is available for applicants with 12 years of schooling. WASSCE is not named specifically; country equivalences are in a table, and minimum WASSCE grades are not stated on the official pages read. Applicants whose diploma does not meet UQAM''s French criteria must submit a recognized French test result; English test minimums (IELTS, TOEFL, Duolingo) are not stated, though some programs need basic English. SAT is not mentioned. The Fall 2027 deadline is March 1, 2027 (some programs earlier).", "sources": ["https://etudier.uqam.ca/sites/default/files/site/all/default/upload/documents/brochure_futurs_etudiants_internationaux_uqam.pdf"], "deadlines": "Fall 2027: March 1, 2027 (some programs have earlier deadlines)."}'::jsonb,'https://etudier.uqam.ca/sites/default/files/site/all/default/upload/documents/brochure_futurs_etudiants_internationaux_uqam.pdf'),
('15494535-de6a-44b3-8dcf-0b37ef2d8ce4','{"ug": "WASSCE/WAEC minimum grades: Not stated on the official site pages reviewed (UNBC publishes requirements by country as PDFs). UNBC requires proof of English proficiency, but the undergraduate IELTS, TOEFL iBT and Duolingo minimums were not found on the official pages that could be opened. SAT: Not stated on the official site. Apply for admission by January 15 to be considered for early entrance awards; general entrance awards are open until April 1.", "sources": ["https://unbc.ca/financial-aid/undergraduate-awards-overview"], "deadlines": "Admission application by January 15 for early entrance award consideration; general entrance awards open until April 1. Official documents due before the start of the semester. Fall admission deadline not confirmed on pages reviewed."}'::jsonb,'https://unbc.ca/financial-aid/undergraduate-awards-overview')
) as v(id,j,link) where s.id=v.id::uuid and s.country='Canada';

