from (values
('1263a1a6-98e8-42a9-8acd-2fd9acd61976','Renewable Entrance Scholarship (International High School Students)','Partial','Undergraduate','International high school applicants entering for the first time with an 85%+ admission average, Fall entry only; automatic consideration on admission; renewable with GPA 10.0 (A-).',null,'https://carleton.ca/awards/entrance-scholarships/','$1,000-$3,000 per year (up to $12,000 over 4 years) based on admission average of 85%+'),
('1263a1a6-98e8-42a9-8acd-2fd9acd61976','President''s Welcome Award for International Students','Partial','Undergraduate','International students paying international fees, entering a bachelor''s degree directly from high school in September; automatic, based on admission grades.',null,'https://admissions.carleton.ca/presidents-welcome-award-for-international-students/','$2,000-$5,000 CAD in first year, on top of other entrance scholarships'),
('e6e07660-48f0-420f-97ec-4dd4c8264457','Supplemental tuition fee exemption program (bachelor''s and master''s)','Partial',null,'A limited number of international bachelor''s and master''s students; exact selection criteria and application process are not stated on the pages reviewed.',null,'https://www.ulaval.ca/espace-etudiant/bourses-et-aide-financiere/financement-pour-les-etudiantes-et-etudiants-de-linternational','International students pay the same tuition as Quebec students (waives the extra international fees)'),
('e6e07660-48f0-420f-97ec-4dd4c8264457','Bourses d''admission (admission scholarships for international students)','Not stated',null,'International students admitted to undergraduate or master''s programs; details are in the scholarship directory.',null,'https://www.ulaval.ca/espace-etudiant/bourses-et-aide-financiere/financement-pour-les-etudiantes-et-etudiants-de-linternational','Amounts not stated; listed in Laval''s scholarship directory'),
('e6e07660-48f0-420f-97ec-4dd4c8264457','Bourses citoyennes et citoyens du monde (BCCM)','Partial','Masters','International research master''s and PhD students, in an excellence stream and an engagement stream; application details are not stated on the page.',null,'https://www.ulaval.ca/espace-etudiant/bourses-et-aide-financiere/financement-pour-les-etudiantes-et-etudiants-de-linternational','$20,000 or $30,000'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Initial Entrance Scholarship (international)','Partial','Undergraduate','International undergraduate applicants are automatically considered based on admission average; scholarship form due March 1.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$500-$2,500'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Chancellor''s Scholarship','Partial','Undergraduate','Entering students with a scholarship average of at least 95%; considered from the application, March 1.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$10,000 per year ($40,000 over 4 years), renewable'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Board of Governors'' Scholarship','Partial','Undergraduate','Entering students with a scholarship average of at least 95%; considered from the application, March 1.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$8,000 per year ($32,000 over 4 years), renewable'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','President''s Scholarship','Partial','Undergraduate','Entering students with a scholarship average of at least 95%; considered from the application, March 1.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$7,000 per year ($28,000 over 4 years), renewable'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Entrance Scholar-Bursaries','Partial','Undergraduate','Average of at least 80%, shows financial need, within 5 years of finishing high school; apply in the Status Portal by March 1.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','Varies; some are renewable, up to $80,000 over 4 years'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Raymond E. Ivany Merit Award','Partial','Undergraduate','Entering first-year full-time domestic or international students; separate essay application (500 words), possible interview; due March 1 (page shows the 2026 cycle).',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$5,000'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Arthur L. Irving Family Foundation Scholarship','Partial','Undergraduate','Entering undergraduates in listed environment-related programs; separate application due March 31.',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','$20,000 per year ($80,000 over 4 years)'),
('e70bc46d-77be-4449-93e1-591f11e04eb0','Acadia Globalization Award','Not stated','Undergraduate','International students who finished Grade 12 at a Canadian high school (so not for applicants coming straight from Ghana).',null,'https://www2.acadiau.ca/student-services/scholarships-financial-aid/international-students/entrance-scholarships.html','Amount not stated'),
('890bc234-8faf-4dcf-b8c5-da0dc787961a','International Entrance Scholarships','Partial','Undergraduate','International students entering any undergraduate level; automatic consideration when applying.',null,'https://ecuad.ca/tuition-fees-undergrad/undergraduate-financial-support-awards/entrance-scholarships/','$2,000-$5,000 CAD'),
('94f34f2e-2f9d-4140-bf3e-f723ea13a7b0','Mount Royal entrance scholarships and awards','Not stated','Undergraduate','International students are eligible for entrance awards unless a donor restricts them. Apply for admission by February 1 for fall and enrol full-time; the online award application is open November 1 to March 1.',null,'https://www.mtroyal.ca/Admission/FinancingYourEducation/ScholarshipsBursaries/awardinfo.htm','Amounts not stated on the policy page; individual awards are listed in MRU''s award database'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','StFX International Scholarships','Partial','Undergraduate','International students with an average of at least 96%, top academic standing, leadership and service; first-semester Grade 12 transcript due by March 1.','2027-03-01','https://stfx.ca/node/4181','$24,000 ($6,000 per year for 4 years, renewable)'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','International Student Ambassador Scholarships','Partial','Undergraduate','International students on a study permit with an 85%+ average and excellence in academics or athletics, leadership and service; listed as a separate application.','2027-03-01','https://stfx.ca/node/4181','$10,000 CAD, one-time'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','International Undergraduate Student Entrance Scholarships','Partial','Undergraduate','International entering students with an 85%+ average, top academic standing, leadership and service; first-semester Grade 12 transcript due by March 1.','2027-03-01','https://stfx.ca/node/4181','$1,000-$5,000, one-time'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','Schwartz International Scholars Entrance Awards','Partial','Undergraduate','Non-Canadian residents entering the BBA from high school with an 85%+ average.','2027-03-01','https://stfx.ca/node/4181','$40,000 ($10,000 per year for 4 years, renewable)'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','Schwartz National Scholars','Partial','Undergraduate','BBA applicants with a 90%+ average plus leadership and service; listed in the international section; application required.','2027-03-01','https://stfx.ca/node/4181','$80,000 CAD ($20,000 per year for 4 years, renewable)'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','StFX Residence Scholarship','Partial','Undergraduate','International students living on campus with an 80%+ average who are academically focused and socially engaged; separate application.','2027-03-01','https://stfx.ca/node/4181','$6,500, one-time'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','National Entrance Scholarships','Partial','Undergraduate','Full-time first-year undergraduates with an 85%+ admission average, described as ''open to all students''; automatic, no separate application.',null,'https://stfx.ca/node/4181','$5,000-$12,000 over 4 years, renewable'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','Faye and David Huestis Family Foundation Scholarship','Partial','Undergraduate','First-year full-time undergraduates with an 85%+ average plus leadership and service; listed in the US/international section; application.','2027-03-01','https://stfx.ca/node/4181','$5,000, one-time'),
('f421fbad-0f9b-4edc-9272-69d7620055cb','StFX Alumni Association Scholarship','Partial','Undergraduate','First-year undergraduates with an 80%+ average, judged on academics, community involvement and extracurriculars; separate application.','2027-03-01','https://stfx.ca/node/4181','$2,000 CAD, one-time'),
('4c3f0735-e2c3-4792-8c4f-042e744ce793','Programme d''excellence d''exemption des droits de scolarité supplémentaires (international tuition exemption)','Partial','Masters','International students admitted full-time to a research master''s (with thesis) or a doctorate, with a cumulative average of 3.3/4.3 or better; automatic, with eligibility confirmed alongside the admission decision; renewable while keeping a 3.0/4.3 average.',null,'https://www.uqar.ca/programmes-formations-et-admission/admission/etudiant-es-etrangers/admission-pour-etudiants-internationaux/programme-dexcellence-dexemption-des-droits-de-scolarite-supplementaires-exiges-des-etudiantes-et-etudiants-internationaux/','Waives the extra international tuition, so students pay Quebec-resident rates'),
('4c3f0735-e2c3-4792-8c4f-042e744ce793','Bourses d''exemption des droits de scolarité supplémentaires (international students outside the Montreal metropolitan area)','Not stated',null,'A Quebec-funded exemption meant to attract international students to regions outside Montreal; the official page link was too long to fetch, so eligibility is not confirmed.',null,'https://www.uqar.ca/programmes-formations-et-admission/admission/etudiant-es-etrangers/admission-pour-etudiants-internationaux/','Exemption from the extra international tuition; details could not be read'),
('03b25832-0531-4f09-ab3a-c82deba3bbde','International Entrance Award','Partial','Undergraduate','New international students with a converted high school average of 90-100% and/or a top 5-10% class ranking, plus activities outside class, strong teacher references and strong English; considered during application review, with limited funds so apply early.',null,'https://d9.upei.ca/scholarships-and-awards/international-student-scholarships','$1,000-$3,000'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','Concordia entrance scholarships (Faculty entrance awards)','Not stated','Undergraduate','First-time, full-time students admitted to a bachelor''s program with CEGEP, Canadian high school or equivalent; mostly automatic by academic ranking. The admissions costs page says all applicants are automatically considered but does not clearly confirm international eligibility.',null,'https://www.concordia.ca/students/financial/scholarships-funding/scholarships.html','Amount not stated; higher-value awards paid over Fall and Winter terms'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','Garnet Key Entrance Award','Partial','Undergraduate','Open to international students; newly admitted full-time students with a 3.0 GPA; application form required.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$850 Deadline on the page: December 3 (year not stated).'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','CIBC Entrance Scholarships at JMSB','Partial','Undergraduate','Open to international students; first-year full-time John Molson School of Business students who identify as BIPOC, LGBTQ+, female or disabled; 500-word statement.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$5,000 Deadline on the page: December 3 (year not stated).'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','CIBC Entrance Scholarships in Engineering','Partial','Undergraduate','Open to international students; first-year computer science, computer engineering or software engineering students who identify as BIPOC, LGBTQ+, female or disabled.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$5,000 Deadline on the page: December 3 (year not stated).'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','Quadbridge Scholarship for Women in Business Technology','Partial','Undergraduate','Open to international students; newly admitted women in Business Technology Management, AGPA 3.3, full-time.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$7,500 Deadline on the page: December 3 (year not stated).'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','Morgan Stanley Race & Ethnic Diversity Scholarship','Partial','Undergraduate','Open to international students; JMSB or Engineering students who identify as Black, Southeast Asian, South Asian or East Asian; GPA 3.30.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$2,500 Deadline on the page: December 3 (year not stated).'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','Colors of Concordia Award','Partial','Undergraduate','Open to international students; full-time bachelor''s students; application form required.',null,'https://www.concordia.ca/students/financial/scholarships-funding/awards.html','$1,000 Deadline on the page: December 3 (year not stated).'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','International Admission Scholarship','Partial','Undergraduate','Top international students, judged on their high school admission average when the offer is made; automatic, no application.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $10,000'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','Regional Excellence Scholarship','Partial','Undergraduate','Top international students from certain regions (regions not named); automatic, no application.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $5,000'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','President''s International Distinction Scholarship','Partial','Undergraduate','25 per year. First-year student-visa holders with a top admission average and leadership; apply through the scholarship application by January 10.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $120,000 over 4 years'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','Chan Pang Kuen Memorial International Distinction Scholarship','Partial','Undergraduate','First-year student-visa holders with a top admission average and leadership; apply by January 10.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $120,000 over 4 years'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','International Leader Scholarship','Partial','Undergraduate','Well-rounded international applicants with strong academics and leadership roles; apply by January 10.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $15,000'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95','Cora Martinson International Scholarship','Partial','Undergraduate','Student-visa holders in the Augustana Faculty with top grades, preferring those with financial need; apply by January 10.',null,'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html','Up to CAN $56,000 over 4 years'),
('25decb60-25d8-47e8-8835-9c35ed464d65','Chancellor''s Award','Partial','Undergraduate','A+ average (about 90-100%) and the stated English test scores. New full-time international first-year undergraduates; apply through the Entrance/Continuing Awards Application (opens in October, first consideration March 1).',null,'https://www.algomau.ca/students/awards-scholarships/entrance-awards/international-scholarships/','$5,000 per year, renewable for up to 3 more years ($20,000 total)'),
('25decb60-25d8-47e8-8835-9c35ed464d65','President''s Award','Partial','Undergraduate','A/A- average (about 85-89%). New full-time international first-year undergraduates; apply through the Entrance/Continuing Awards Application (opens in October, first consideration March 1).',null,'https://www.algomau.ca/students/awards-scholarships/entrance-awards/international-scholarships/','$2,500, one-time'),
('25decb60-25d8-47e8-8835-9c35ed464d65','Dean''s Award','Partial','Undergraduate','B+ average (about 80-84%). New full-time international first-year undergraduates; apply through the Entrance/Continuing Awards Application (opens in October, first consideration March 1).',null,'https://www.algomau.ca/students/awards-scholarships/entrance-awards/international-scholarships/','$1,000, one-time'),
('25decb60-25d8-47e8-8835-9c35ed464d65','Award of Excellence','Partial','Undergraduate','B average (about 75-79%). New full-time international first-year undergraduates; apply through the Entrance/Continuing Awards Application (opens in October, first consideration March 1).',null,'https://www.algomau.ca/students/awards-scholarships/entrance-awards/international-scholarships/','$500, one-time'),
('25decb60-25d8-47e8-8835-9c35ed464d65','International Scholars Degree Award','Not stated','Undergraduate','Can be combined with the entrance awards where eligible; details are not stated.',null,'https://www.algomau.ca/students/awards-scholarships/entrance-awards/international-scholarships/','Amount not stated'),
('66916c52-54ff-4d03-b765-f1289349f38a','Automatic entrance scholarships (incl. Diamond Jubilee Entrance Scholarships)','Not stated','Undergraduate','MSVU says international students coming from high school may be eligible for entrance scholarships considered automatically on admission. Diamond Jubilee awards go to high school applicants with an 80%+ average who apply by March 1; no separate application.',null,'https://www.msvu.ca/future-students/money-matters/scholarships-awards/undergraduate-scholarships/entrance-scholarships/','Amounts not stated Deadline on the page: March 1 (year not stated).'),
('66916c52-54ff-4d03-b765-f1289349f38a','President''s Scholarship','Not stated','Undergraduate','Top applicants with a high average and a record of school or community contribution; application form, essay, references and resume to scholarships@msvu.ca. No citizenship limit stated.',null,'https://www.msvu.ca/future-students/money-matters/scholarships-awards/undergraduate-scholarships/entrance-scholarships/','Amount not stated; limited number Deadline on the page: February 15 (year not stated).'),
('66916c52-54ff-4d03-b765-f1289349f38a','Student Leadership Award','Partial','Undergraduate','New students with high standards of leadership and achievement; separate application. No citizenship limit stated.',null,'https://www.msvu.ca/future-students/money-matters/scholarships-awards/undergraduate-scholarships/entrance-scholarships/','A room in residence at no charge Deadline on the page: March 1 (year not stated).'),
('66916c52-54ff-4d03-b765-f1289349f38a','First Choice Airways Endowed Scholarship','Not stated','Undergraduate','Entering students with a demonstrated commitment to volunteering; resume to scholarships@msvu.ca. No citizenship limit stated.',null,'https://www.msvu.ca/future-students/money-matters/scholarships-awards/undergraduate-scholarships/entrance-scholarships/','Amount not stated Deadline on the page: March 1 (year not stated).'),
('c50b6fa3-e068-4a5c-9a56-4ac3226e73e4','Chancellor''s International Scholarship','Partial','Undergraduate','An entering international student chosen for academic excellence and leadership; renewable with a 3.7 annual average. Whether you must apply is not stated.',null,'https://communications.stu.ca/entrancescholarships','Full international tuition (one award), renewable'),
('c50b6fa3-e068-4a5c-9a56-4ac3226e73e4','President''s International Scholarship','Partial','Undergraduate','Entering international students, chosen on academic excellence alone; renewable with a 3.7 annual average.',null,'https://communications.stu.ca/entrancescholarships','Varies, up to full tuition; renewable for 3 more years'),
('c50b6fa3-e068-4a5c-9a56-4ac3226e73e4','Aranyam Bora Memorial Award','Partial','Undergraduate','An entering international student chosen on academic merit, activities outside class and cross-cultural understanding.',null,'https://communications.stu.ca/entrancescholarships','$500 (one award)'),
